class PublishError(Exception):
    def __init__(self, errors):
        super().__init__(f"{len(errors)} handler(s) failed")
        self.errors = errors


class EventBus:
    def __init__(self):
        self._handlers = {}

    def subscribe(self, event, handler, priority=0):
        handlers = self._handlers.setdefault(event, [])
        entry = (priority, handler, object())
        handlers.append(entry)
        handlers.sort(key=lambda item: -item[0])

        def unsubscribe():
            if entry in handlers:
                handlers.remove(entry)

        return unsubscribe

    def publish(self, event, payload=None):
        handlers = self._handlers.get(event, [])
        errors = []
        for entry in list(handlers):
            if entry not in handlers:
                continue
            try:
                entry[1](payload)
            except Exception as error:
                errors.append(error)
        if errors:
            raise PublishError(errors)
